unit Notes.Format;

uses Notes.Model, Std.Array, Std.Conv, Std.Dict, Std.Option, Std.Result, Std.Str, Std.Toml;

const
  NoteFormatVersion: integer := 1;

function MissingField(Name: string): string;
begin
  return ('Missing required note field `' + Name) + '`'
end;

function FieldString(Fields: dict of string to TomlValue; Name: string): result of string, string;
begin
  case Std.Dict.Get(Fields, Name) of
    Some(Value):
    begin
      case Value of
        TomlValue.String(Text):
        begin
          return Ok(Text)
        end
        else
        begin
          return Error(('Note field `' + Name) + '` must be a string')
        end
      end
    end;
    None:
    begin
      return Error(MissingField(Name))
    end
  end
end;

function FieldInteger(Fields: dict of string to TomlValue; Name: string): result of integer, string;
begin
  case Std.Dict.Get(Fields, Name) of
    Some(Value):
    begin
      case Value of
        TomlValue.Integer(Number):
        begin
          return Ok(Number)
        end
        else
        begin
          return Error(('Note field `' + Name) + '` must be an integer')
        end
      end
    end;
    None:
    begin
      return Error(MissingField(Name))
    end
  end
end;

function FieldBoolean(Fields: dict of string to TomlValue; Name: string): result of boolean, string;
begin
  case Std.Dict.Get(Fields, Name) of
    Some(Value):
    begin
      case Value of
        TomlValue.Boolean(Flag):
        begin
          return Ok(Flag)
        end
        else
        begin
          return Error(('Note field `' + Name) + '` must be a boolean')
        end
      end
    end;
    None:
    begin
      return Error(MissingField(Name))
    end
  end
end;

function FieldTags(Fields: dict of string to TomlValue): result of array of string, string;
begin
  case Std.Dict.Get(Fields, 'tags') of
    Some(Value):
    begin
      case Value of
        TomlValue.Array(Items):
        begin
          mutable var Tags: array of string := [];
          for Index: integer := 0 to Std.Array.Length(Items) - 1 do
          begin
            case Items[Index] of
              TomlValue.String(Tag):
              begin
                Std.Array.Push(Tags, Tag)
              end
              else
              begin
                return Error('Every note tag must be a string')
              end
            end
          end;

          return Ok(Tags)
        end
        else
        begin
          return Error('Note field `tags` must be an array')
        end
      end
    end;
    None:
    begin
      return Error(MissingField('tags'))
    end
  end
end;

function ParseFields(Fields: dict of string to TomlValue; Body: string): result of Note, string;
begin
  var Version: integer := try FieldInteger(Fields, 'format');
  if Version <> NoteFormatVersion then
  begin
    return Error(('Unsupported note format version ' + IntToStr(Version)) + '; expected 1')
  end;
  var Id: string := try FieldString(Fields, 'id');
  if Std.Str.Trim(Id) = '' then
  begin
    return Error('Note field `id` must not be empty')
  end;
  var Title: string := try FieldString(Fields, 'title');
  var Created: integer := try FieldInteger(Fields, 'created_ms');
  var Updated: integer := try FieldInteger(Fields, 'updated_ms');
  if (Created < 0) or (Updated < 0) then
  begin
    return Error('Note timestamps must not be negative')
  end;

  return Ok(record
    Id := Id;
    Title := Title;
    CreatedMillis := Created;
    UpdatedMillis := Updated;
    Tags := try FieldTags(Fields);
    Pinned := try FieldBoolean(Fields, 'pinned');
    Archived := try FieldBoolean(Fields, 'archived');
    Body := Body;
    Path := '';
  end)
end;

// Parses one UTF-8 `.note` document with TOML frontmatter.
public function NoteParse(Text: string): result of Note, string;
begin
  var NewLine: string := Std.Str.Chr(10);
  var Source: string := Std.Str.Replace(Std.Str.Replace(Text, Std.Str.Chr(13) + NewLine, NewLine), Std.Str.Chr(13), NewLine);
  var Prefix: string := '+++' + NewLine;
  if not Std.Str.StartsWith(Source, Prefix) then
  begin
    return Error('A .note file must start with a `+++` TOML header')
  end;
  var Remaining: string := Std.Str.Substring(Source, Std.Str.Length(Prefix), Std.Str.Length(Source) -
                                                                             Std.Str.Length(Prefix));
  var Boundary: string := (NewLine + '+++') + NewLine;
  var BoundaryIndex: integer := Std.Str.IndexOf(Remaining, Boundary);
  if BoundaryIndex < 0 then
  begin
    return Error('A .note file must close its TOML header with `+++`')
  end;
  var Header: string := Std.Str.Substring(Remaining, 0, BoundaryIndex);
  var BodyStart: integer := BoundaryIndex + Std.Str.Length(Boundary);
  var Body: string := Std.Str.Substring(Remaining, BodyStart, Std.Str.Length(Remaining) - BodyStart);
  case Std.Toml.Parse(Header) of
    Ok(Value):
    begin
      case Value of
        TomlValue.Table(Fields):
        begin
          return ParseFields(Fields, Body)
        end
        else
        begin
          return Error('The .note metadata root must be a TOML table')
        end
      end
    end;
    Error(Message):
    begin
      return Error('Invalid .note TOML header: ' + Message)
    end
  end
end;

// Encodes one note as deterministic TOML frontmatter and Markdown body text.
public function NoteStringify(NoteValue: Note): string;
begin
  mutable var TagValues: array of TomlValue := [];
  for Index: integer := 0 to Std.Array.Length(NoteValue.Tags) - 1 do
  begin
    Std.Array.Push(TagValues, TomlValue.String(NoteValue.Tags[Index]))
  end;
  var Header: TomlValue := TomlValue.Table(['format': TomlValue.Integer(NoteFormatVersion), 'id': TomlValue.String(NoteValue.Id), 'title': TomlValue.String(NoteValue.Title), 'created_ms': TomlValue.Integer(NoteValue.CreatedMillis), 'updated_ms': TomlValue.Integer(NoteValue.UpdatedMillis), 'tags': TomlValue.Array(TagValues), 'pinned': TomlValue.Boolean(NoteValue.Pinned), 'archived': TomlValue.Boolean(NoteValue.Archived)]);
  var NewLine: string := Std.Str.Chr(10);
  return ((((('+++' + NewLine) + Std.Str.TrimRight(Std.Toml.Stringify(Header))) + NewLine) + '+++') + NewLine) +
         NoteValue.Body
end;

unit Notes.Model;

uses Std.Array, Std.Console, Std.Conv, Std.Str, Std.Tui;

public type
  // One persisted `.note` document and its source path.
  Note = record
    public Id: string;
    public Title: string;
    public CreatedMillis: integer;
    public UpdatedMillis: integer;
    public Tags: array of string;
    public Pinned: boolean;
    public Archived: boolean;
    public Body: string;
    public Path: string;
  end;
  // One note file that could not be read or parsed.
  NoteIssue = record
    public Path: string;
    public Message: string;
  end;
  // Complete result of loading one notes directory.
  NotesLoad = record
    public Notes: array of Note;
    public Issues: array of NoteIssue;
  end;
  // Visible pane in a narrow terminal.
  NotesPane = enum
    List;
    Editor;
  end;
  // Active modal layer, if any.
  NotesOverlay = enum
    Closed;
    Commands;
    Help;
    QuitConfirmation;
    SaveFailure;
  end;
  // Complete immutable application state supplied to the MVU view.
  NotesModel = record
    public Directory: string;
    public Notes: array of Note;
    public Issues: array of NoteIssue;
    public Selected: integer;
    public Search: string;
    public SearchCaret: integer;
    public TitleCaret: integer;
    public TagsText: string;
    public TagsCaret: integer;
    public BodyCaret: integer;
    public BodyOffset: TuiPoint;
    public Focus: integer;
    public Pane: NotesPane;
    public Overlay: NotesOverlay;
    public Dirty: boolean;
    public Status: string;
    public ErrorMessage: string;
    public Width: integer;
    public Height: integer;
  end;

// Creates a new unsaved note with stable identity and timestamps.
public function NoteCreate(Id: string; TimestampMillis: integer): Note;
begin
  return record
    Id := Id;
    Title := 'Untitled note';
    CreatedMillis := TimestampMillis;
    UpdatedMillis := TimestampMillis;
    Tags := [];
    Pinned := false;
    Archived := false;
    Body := '';
    Path := '';
  end
end;

// Creates initial application state from a directory load result.
public function NotesModelCreate(Directory: string; Loaded: NotesLoad): NotesModel;
begin
  mutable var Selected: integer := -1;
  mutable var Focus: integer := 1;
  mutable var Pane: NotesPane := NotesPane.List;
  mutable var Status: string := 'Ready';
  mutable var TitleCaret: integer := 0;
  mutable var TagsText: string := '';
  mutable var TagsCaret: integer := 0;
  if Std.Array.Length(Loaded.Notes) > 0 then
  begin
    Selected := 0;
    Focus := 3;
    Pane := NotesPane.Editor;
    TitleCaret := Std.Str.Length(Loaded.Notes[0].Title);
    TagsText := Std.Str.Join(Loaded.Notes[0].Tags, ', ');
    TagsCaret := Std.Str.Length(TagsText)
  end;

  if Std.Array.Length(Loaded.Issues) > 0 then
  begin
    Status := IntToStr(Std.Array.Length(Loaded.Issues)) + ' invalid note file(s)'
  end;

  return record
    Directory := Directory;
    Notes := Loaded.Notes;
    Issues := Loaded.Issues;
    Selected := Selected;
    Search := '';
    SearchCaret := 0;
    TitleCaret := TitleCaret;
    TagsText := TagsText;
    TagsCaret := TagsCaret;
    BodyCaret := 0;
    BodyOffset := TuiPoint.Create(0, 0);
    Focus := Focus;
    Pane := Pane;
    Overlay := NotesOverlay.Closed;
    Dirty := false;
    Status := Status;
    ErrorMessage := '';
    Width := 100;
    Height := 30;
  end
end;

// Formats a note's tags for the controlled metadata input.
public function NoteTagsText(NoteValue: Note): string;
begin
  return Std.Str.Join(NoteValue.Tags, ', ')
end;

// Parses, trims, and deduplicates comma-separated tags.
public function NoteTagsFromText(Text: string): array of string;
begin
  mutable var Tags: array of string := [];
  var Parts: array of string := Std.Str.Split(Text, ',');
  for Index: integer := 0 to Std.Array.Length(Parts) - 1 do
  begin
    var Tag: string := Std.Str.Trim(Parts[Index]);
    if (Tag <> '') and (not Std.Array.Contains(Tags, Tag)) then
    begin
      Std.Array.Push(Tags, Tag)
    end
  end;

  return Tags
end;

// Reports whether an active note matches a case-insensitive query.
public function NoteMatches(NoteValue: Note; Search: string): boolean;
begin
  var Query: string := Std.Str.ToLower(Std.Str.Trim(Search));
  if Query = '' then
  begin
    return not NoteValue.Archived
  end;

  if NoteValue.Archived then
  begin
    return false
  end;

  return (Std.Str.Contains(Std.Str.ToLower(NoteValue.Title), Query) or Std.Str.Contains(Std.Str.ToLower(NoteValue.Body), Query)) or
         Std.Str.Contains(Std.Str.ToLower(NoteTagsText(NoteValue)), Query)
end;

// Returns source-array indices for all visible filtered notes.
public function NotesFilteredIndices(Notes: array of Note; Search: string): array of integer;
begin
  mutable var Indices: array of integer := [];
  for Index: integer := 0 to Std.Array.Length(Notes) - 1 do
  begin
    if NoteMatches(Notes[Index], Search) then
    begin
      Std.Array.Push(Indices, Index)
    end
  end;

  return Indices
end;

function ClipListText(Text: string; MaximumWidth: integer): string;
begin
  if MaximumWidth <= 0 then
  begin
    return ''
  end;

  if Std.Console.DisplayWidth(Text) <= MaximumWidth then
  begin
    return Text
  end;

  if MaximumWidth = 1 then
  begin
    return '…'
  end;
  mutable var Clipped: string := '';
  mutable var Width: integer := 0;
  var ContentWidth: integer := MaximumWidth - 1;
  for Grapheme: string in Std.Console.SplitGraphemes(Text) do
  begin
    var GraphemeWidth: integer := Std.Console.DisplayWidth(Grapheme);
    if Width + GraphemeWidth > ContentWidth then
    begin
      return Clipped + '…'
    end;

    Clipped := Clipped + Grapheme;
    Width := Width + GraphemeWidth
  end;

  return Clipped
end;

// Builds width-bounded list labels for all visible filtered notes.
public function NotesListItems(Notes: array of Note; Search: string; MaximumWidth: integer): array of string;
begin
  mutable var Items: array of string := [];
  var Indices: array of integer := NotesFilteredIndices(Notes, Search);
  for Index: integer := 0 to Std.Array.Length(Indices) - 1 do
  begin
    var NoteValue: Note := Notes[Indices[Index]];
    mutable var Prefix: string := '  ';
    if NoteValue.Pinned then
    begin
      Prefix := '★ '
    end;
    mutable var Tags: string := NoteTagsText(NoteValue);
    if Tags <> '' then
    begin
      Tags := '  ·  ' + Tags
    end;

    Std.Array.Push(Items, ClipListText((Prefix + NoteValue.Title) + Tags, MaximumWidth))
  end;

  return Items
end;

unit Notes.Repository;

uses
  Notes.Format, Notes.Model, Std.Array, Std.Conv, Std.Fs, Std.Path, Std.Random, Std.Result, Std.Str,
  Std.Time;

// Creates the notes directory or validates that it already exists.
public function NotesEnsureDirectory(Directory: string): result of boolean, string;
begin
  if Std.Fs.Exists(Directory) then
  begin
    if Std.Fs.IsDir(Directory) then
    begin
      return Ok(true)
    end;

    return Error('Notes path exists but is not a directory: ' + Directory)
  end;

  return Std.Fs.CreateDir(Directory)
end;

// Resolves a note's existing or identity-derived `.note` path.
public function NoteFilePath(Directory: string; NoteValue: Note): string;
begin
  if NoteValue.Path <> '' then
  begin
    return NoteValue.Path
  end;

  return Std.Path.Join([Directory, NoteValue.Id + '.note'])
end;

function NoteComesBefore(Left: Note; Right: Note): boolean;
begin
  if Left.Pinned <> Right.Pinned then
  begin
    return Left.Pinned
  end;

  return Left.UpdatedMillis > Right.UpdatedMillis
end;

// Sorts pinned notes first and then by descending update timestamp.
public function NotesSort(Notes: array of Note): array of Note;
begin
  mutable var Sorted: array of Note := Notes;
  for Left: integer := 0 to Std.Array.Length(Sorted) - 1 do
  begin
    for Right: integer := Left + 1 to Std.Array.Length(Sorted) - 1 do
    begin
      if NoteComesBefore(Sorted[Right], Sorted[Left]) then
      begin
        var Previous: Note := Sorted[Left];
        Sorted[Left] := Sorted[Right];
        Sorted[Right] := Previous
      end
    end
  end;

  return Sorted
end;

// Loads valid notes and preserves invalid files as visible issues.
public function NotesLoadDirectory(Directory: string): result of NotesLoad, string;
begin
  var DirectoryReady: boolean := try NotesEnsureDirectory(Directory);
  var Paths: array of string := try Std.Fs.Glob(Std.Path.Join([Directory, '*.note']));
  mutable var Notes: array of Note := [];
  mutable var Issues: array of NoteIssue := [];
  for Index: integer := 0 to Std.Array.Length(Paths) - 1 do
  begin
    var Path: string := Paths[Index];
    case Std.Fs.ReadText(Path) of
      Ok(Text):
      begin
        case NoteParse(Text) of
          Ok(NoteValue):
          begin
            mutable var Loaded: Note := NoteValue;
            Loaded.Path := Path;
            Std.Array.Push(Notes, Loaded)
          end;
          Error(Message):
          begin
            Std.Array.Push(Issues, record
              Path := Path;
              Message := Message;
            end)
          end
        end
      end;
      Error(Message):
      begin
        Std.Array.Push(Issues, record
          Path := Path;
          Message := Message;
        end)
      end
    end
  end;

  return Ok(record
    Notes := NotesSort(Notes);
    Issues := Issues;
  end)
end;

// Atomically writes one note to its stable file path.
public function NotesSave(Directory: string; NoteValue: Note): result of boolean, string;
begin
  var DirectoryReady: boolean := try NotesEnsureDirectory(Directory);
  return Std.Fs.WriteTextAtomic(NoteFilePath(Directory, NoteValue), NoteStringify(NoteValue))
end;

// Generates an unused timestamp-and-random identity in one directory.
public function NotesCreateId(Directory: string; TimestampMillis: integer): string;
begin
  mutable var Candidate: string := '';
  repeat
    Candidate := (IntToStr(TimestampMillis) + '-') + IntToStr(Std.Random.RandomInt(100000, 999999))
  until not Std.Fs.Exists(Std.Path.Join([Directory, Candidate + '.note']));
  return Candidate
end;

// Creates an in-memory draft with a new identity and current timestamp.
public function NotesCreateDraft(Directory: string): Note;
begin
  var Now: integer := Std.Time.TimestampMillis();
  return NoteCreate(NotesCreateId(Directory, Now), Now)
end;

unit Notes.Update;

uses
  Notes.Model, Notes.Repository, Std.Array, Std.Console, Std.Conv, Std.Option, Std.Str, Std.Time,
  Std.Tui;

const
  SearchControl: integer := 1;
  ListControl: integer := 2;
  TitleControl: integer := 3;
  TagsControl: integer := 4;
  BodyControl: integer := 5;
  SearchChangedAction: integer := 1;
  SelectionChangedAction: integer := 2;
  TitleChangedAction: integer := 3;
  TagsChangedAction: integer := 4;
  BodyChangedAction: integer := 5;
  NewNoteAction: integer := 10;
  SaveNoteAction: integer := 11;
  TogglePinAction: integer := 12;
  ArchiveNoteAction: integer := 13;
  CommandsAction: integer := 14;
  HelpAction: integer := 15;
  CloseOverlayAction: integer := 16;
  SaveAndQuitAction: integer := 17;
  DiscardAndQuitAction: integer := 18;

function SelectedExists(State: NotesModel): boolean;
begin
  return (State.Selected >= 0) and (State.Selected < Std.Array.Length(State.Notes))
end;

function WithNote(State: NotesModel; Index: integer; NoteValue: Note): NotesModel;
begin
  mutable var Notes: array of Note := State.Notes;
  Notes[Index] := NoteValue;
  mutable var Next: NotesModel := State;
  Next.Notes := Notes;
  return Next
end;

function ResortSelected(State: NotesModel; SelectedId: string): NotesModel;
begin
  mutable var Next: NotesModel := State;
  Next.Notes := NotesSort(State.Notes);
  Next.Selected := -1;
  for Index: integer := 0 to Std.Array.Length(Next.Notes) - 1 do
  begin
    if Next.Notes[Index].Id = SelectedId then
    begin
      Next.Selected := Index;
      return Next
    end
  end;

  return Next
end;

function WithEditorFields(State: NotesModel; Selected: integer): NotesModel;
begin
  mutable var Next: NotesModel := State;
  Next.Selected := Selected;
  Next.Pane := NotesPane.Editor;
  Next.Focus := BodyControl;
  Next.Dirty := false;
  Next.BodyCaret := 0;
  Next.BodyOffset := TuiPoint.Create(0, 0);
  if (Selected >= 0) and (Selected < Std.Array.Length(State.Notes)) then
  begin
    var NoteValue: Note := State.Notes[Selected];
    Next.TitleCaret := Std.Str.Length(NoteValue.Title);
    Next.TagsText := NoteTagsText(NoteValue);
    Next.TagsCaret := Std.Str.Length(Next.TagsText)
  end
  else
  begin
    Next.TitleCaret := 0;
    Next.TagsText := '';
    Next.TagsCaret := 0
  end;

  return Next
end;

// Persists the selected dirty note and returns the resulting UI state.
public function NotesPersistCurrent(State: NotesModel): NotesModel;
begin
  if (not State.Dirty) or (not SelectedExists(State)) then
  begin
    return State
  end;
  mutable var Next: NotesModel := State;
  mutable var NoteValue: Note := Next.Notes[Next.Selected];
  NoteValue.UpdatedMillis := Std.Time.TimestampMillis();
  NoteValue.Path := NoteFilePath(Next.Directory, NoteValue);
  case NotesSave(Next.Directory, NoteValue) of
    Ok(Written):
    begin
      Next := WithNote(Next, Next.Selected, NoteValue);
      Next := ResortSelected(Next, NoteValue.Id);
      Next.Dirty := false;
      Next.Status := 'Saved ' + NoteValue.Title;
      return Next
    end;
    Error(Message):
    begin
      Next.Overlay := NotesOverlay.SaveFailure;
      Next.ErrorMessage := Message;
      Next.Status := 'Save failed';
      return Next
    end
  end
end;

function SelectedFilteredPosition(State: NotesModel): integer;
begin
  var Indices: array of integer := NotesFilteredIndices(State.Notes, State.Search);
  for Index: integer := 0 to Std.Array.Length(Indices) - 1 do
  begin
    if Indices[Index] = State.Selected then
    begin
      return Index
    end
  end;

  return -1
end;

function SelectFiltered(State: NotesModel; Position: integer): NotesModel;
begin
  var Indices: array of integer := NotesFilteredIndices(State.Notes, State.Search);
  if (Position < 0) or (Position >= Std.Array.Length(Indices)) then
  begin
    return State
  end;
  var Saved: NotesModel := NotesPersistCurrent(State);
  if Saved.Dirty or (Saved.Overlay = NotesOverlay.SaveFailure) then
  begin
    return Saved
  end;
  mutable var Next: NotesModel := WithEditorFields(Saved, Indices[Position]);
  Next.Pane := NotesPane.List;
  Next.Focus := ListControl;
  return Next
end;

function CreateNote(State: NotesModel): NotesModel;
begin
  var Saved: NotesModel := NotesPersistCurrent(State);
  if Saved.Dirty or (Saved.Overlay = NotesOverlay.SaveFailure) then
  begin
    return Saved
  end;
  mutable var Next: NotesModel := Saved;
  mutable var Draft: Note := NotesCreateDraft(Next.Directory);
  Draft.Path := NoteFilePath(Next.Directory, Draft);
  case NotesSave(Next.Directory, Draft) of
    Ok(Written):
    begin
      mutable var Notes: array of Note := Next.Notes;
      Std.Array.Push(Notes, Draft);
      Next.Notes := Notes;
      Next := ResortSelected(Next, Draft.Id);
      Next := WithEditorFields(Next, Next.Selected);
      Next.TitleCaret := Std.Str.Length(Draft.Title);
      Next.Focus := TitleControl;
      Next.Status := 'Created a new note';
      return Next
    end;
    Error(Message):
    begin
      Next.Overlay := NotesOverlay.SaveFailure;
      Next.ErrorMessage := Message;
      Next.Status := 'Could not create note';
      return Next
    end
  end
end;

function TogglePin(State: NotesModel): NotesModel;
begin
  if not SelectedExists(State) then
  begin
    return State
  end;
  mutable var Next: NotesModel := State;
  mutable var NoteValue: Note := Next.Notes[Next.Selected];
  NoteValue.Pinned := not NoteValue.Pinned;
  Next := WithNote(Next, Next.Selected, NoteValue);
  Next.Dirty := true;
  Next.Status := 'Pin changed';
  return NotesPersistCurrent(Next)
end;

function SelectFirstVisible(State: NotesModel): NotesModel;
begin
  var Indices: array of integer := NotesFilteredIndices(State.Notes, State.Search);
  if Std.Array.Length(Indices) = 0 then
  begin
    mutable var Empty: NotesModel := State;
    Empty.Selected := -1;
    Empty.Pane := NotesPane.List;
    Empty.Focus := ListControl;
    return Empty
  end;

  return WithEditorFields(State, Indices[0])
end;

function ArchiveNote(State: NotesModel): NotesModel;
begin
  if not SelectedExists(State) then
  begin
    return State
  end;
  mutable var Next: NotesModel := State;
  mutable var NoteValue: Note := Next.Notes[Next.Selected];
  NoteValue.Archived := true;
  Next := WithNote(Next, Next.Selected, NoteValue);
  Next.Dirty := true;
  Next := NotesPersistCurrent(Next);
  if Next.Dirty or (Next.Overlay = NotesOverlay.SaveFailure) then
  begin
    return Next
  end;

  Next.Status := 'Note archived';
  return SelectFirstVisible(Next)
end;

function HandleAction(State: NotesModel; Action: integer; Cmd: TuiCmdOutput): NotesModel;
begin
  if Action = NewNoteAction then
  begin
    return CreateNote(State)
  end;

  if Action = SaveNoteAction then
  begin
    return NotesPersistCurrent(State)
  end;

  if Action = TogglePinAction then
  begin
    return TogglePin(State)
  end;

  if Action = ArchiveNoteAction then
  begin
    return ArchiveNote(State)
  end;

  if Action = CommandsAction then
  begin
    mutable var Next: NotesModel := State;
    Next.Overlay := NotesOverlay.Commands;
    return Next
  end;

  if Action = HelpAction then
  begin
    mutable var Next: NotesModel := State;
    Next.Overlay := NotesOverlay.Help;
    return Next
  end;

  if Action = CloseOverlayAction then
  begin
    mutable var Next: NotesModel := State;
    Next.Overlay := NotesOverlay.Closed;
    Next.ErrorMessage := '';
    return Next
  end;

  if Action = SaveAndQuitAction then
  begin
    var Saved: NotesModel := NotesPersistCurrent(State);
    if not Saved.Dirty and (Saved.Overlay <> NotesOverlay.SaveFailure) then
    begin
      Cmd.Set(TuiCmd.Quit)
    end;

    return Saved
  end;

  if Action = DiscardAndQuitAction then
  begin
    Cmd.Set(TuiCmd.Quit);
    return State
  end;

  return State
end;

function RequestQuit(State: NotesModel; Cmd: TuiCmdOutput): NotesModel;
begin
  if State.Dirty then
  begin
    mutable var Next: NotesModel := State;
    Next.Overlay := NotesOverlay.QuitConfirmation;
    return Next
  end;

  Cmd.Set(TuiCmd.Quit);
  return State
end;

function HandleShortcut(State: NotesModel; Key: TuiKeyEvent; Cmd: TuiCmdOutput): NotesModel;
begin
  if Key.kind = Std.Console.KeyKind.F1 then
  begin
    return HandleAction(State, HelpAction, Cmd)
  end;

  if ((Key.kind = Std.Console.KeyKind.Enter) and (State.Focus = ListControl)) and
     SelectedExists(State) then
  begin
    mutable var Next: NotesModel := State;
    Next.Focus := BodyControl;
    Next.Pane := NotesPane.Editor;
    return Next
  end;

  if (((Key.kind = Std.Console.KeyKind.Character) and Key.alt) and (not Key.ctrl)) and
     (not Key.meta) then
  begin
    case Key.ch of
      'x', 'X':
      begin
        return RequestQuit(State, Cmd)
      end
    end
  end;

  if (Key.kind <> Std.Console.KeyKind.Character) or (not Key.ctrl) then
  begin
    return State
  end;

  case Key.ch of
    'n', 'N':
    begin
      return HandleAction(State, NewNoteAction, Cmd)
    end;
    's', 'S':
    begin
      return HandleAction(State, SaveNoteAction, Cmd)
    end;
    'f', 'F':
    begin
      mutable var Next: NotesModel := State;
      Next.Focus := SearchControl;
      Next.Pane := NotesPane.List;
      return Next
    end;
    'k', 'K':
    begin
      return HandleAction(State, CommandsAction, Cmd)
    end;
    'p', 'P':
    begin
      return HandleAction(State, TogglePinAction, Cmd)
    end;
    '1':
    begin
      mutable var Next: NotesModel := State;
      Next.Focus := SearchControl;
      Next.Pane := NotesPane.List;
      return Next
    end;
    '2':
    begin
      mutable var Next: NotesModel := State;
      Next.Focus := BodyControl;
      Next.Pane := NotesPane.Editor;
      return Next
    end
  end;

  return State
end;

// Applies one routed TUI message to the Notes application model.
public function NotesUpdate(State: NotesModel; Msg: TuiMsg; Cmd: TuiCmdOutput): NotesModel;
begin
  Cmd.Set(TuiCmd.NoCommand);
  case Msg of
    TuiMsg.Key(Key):
    begin
      return HandleShortcut(State, Key, Cmd)
    end;
    TuiMsg.Resize(Size):
    begin
      mutable var Next: NotesModel := State;
      Next.Width := Size.Width;
      Next.Height := Size.Height;
      return Next
    end;
    TuiMsg.FocusChanged(Previous, Current):
    begin
      case Current of
        Some(CurrentId):
        begin
          mutable var Next: NotesModel := State;
          Next.Focus := CurrentId.Value;
          return Next
        end;
        None:
        begin
          return State
        end
      end
    end;
    TuiMsg.TextChanged(Source, Action, Text, Caret):
    begin
      mutable var Next: NotesModel := State;
      if Action.Value = SearchChangedAction then
      begin
        Next.Search := Text;
        Next.SearchCaret := Caret;
        Next.Status := IntToStr(Std.Array.Length(NotesFilteredIndices(Next.Notes, Text))) +
                       ' matching note(s)';
        return Next
      end;

      if (Action.Value = TitleChangedAction) and SelectedExists(Next) then
      begin
        mutable var NoteValue: Note := Next.Notes[Next.Selected];
        NoteValue.Title := Text;
        Next := WithNote(Next, Next.Selected, NoteValue);
        Next.TitleCaret := Caret;
        Next.Dirty := true;
        Next.Status := 'Unsaved changes';
        return Next
      end;

      if (Action.Value = TagsChangedAction) and SelectedExists(Next) then
      begin
        Next.TagsText := Text;
        Next.TagsCaret := Caret;
        mutable var NoteValue: Note := Next.Notes[Next.Selected];
        NoteValue.Tags := NoteTagsFromText(Text);
        Next := WithNote(Next, Next.Selected, NoteValue);
        Next.Dirty := true;
        Next.Status := 'Unsaved changes';
        return Next
      end;

      return Next
    end;
    TuiMsg.TextAreaChanged(Source, Action, Text, Caret, Offset):
    begin
      mutable var Next: NotesModel := State;
      if (Action.Value = BodyChangedAction) and SelectedExists(Next) then
      begin
        mutable var NoteValue: Note := Next.Notes[Next.Selected];
        NoteValue.Body := Text;
        Next := WithNote(Next, Next.Selected, NoteValue);
        Next.BodyCaret := Caret;
        Next.BodyOffset := Offset;
        Next.Dirty := true;
        Next.Status := 'Unsaved changes'
      end;

      return Next
    end;
    TuiMsg.SelectionChanged(Source, Action, Selected):
    begin
      if Action.Value = SelectionChangedAction then
      begin
        return SelectFiltered(State, Selected)
      end;

      return State
    end;
    TuiMsg.Action(Source, Action):
    begin
      return HandleAction(State, Action.Value, Cmd)
    end;
    TuiMsg.QuitRequested:
    begin
      if State.Overlay <> NotesOverlay.Closed then
      begin
        return HandleAction(State, CloseOverlayAction, Cmd)
      end;

      return State
    end;
    TuiMsg.Pointer(Pointer):
    begin
      return State
    end;
    TuiMsg.Tick(Delta):
    begin
      return State
    end;
    TuiMsg.CheckChanged(CheckSource, CheckAction, Checked):
    begin
      return State
    end;
    TuiMsg.ScrollChanged(ScrollSource, ScrollAction, ScrollOffset):
    begin
      return State
    end;
    TuiMsg.MenuChanged(MenuSource, MenuAction, MenuState):
    begin
      return State
    end
  end
end;

// Maps the source note selection to its position in the filtered list.
public function NotesSelectedFilteredPosition(State: NotesModel): integer;
begin
  return SelectedFilteredPosition(State)
end;

program Notes;

uses
  Notes.Model, Notes.Repository, Notes.Theme, Notes.Update, Notes.View, Std.Args, Std.Console,
  Std.Random, Std.Tui;

function NotesDirectory(): string;
begin
  if Std.Args.ParamCount() > 0 then
  begin
    return Std.Args.ParamStr(0)
  end;

  return 'notes'
end;

begin
  Std.Random.Randomize();
  var Directory: string := NotesDirectory();
  case NotesLoadDirectory(Directory) of
    Ok(Loaded):
    begin
      mutable var Initial: NotesModel := NotesModelCreate(Directory, Loaded);
      Initial.Width := Std.Console.ScreenWidth();
      Initial.Height := Std.Console.ScreenHeight();
      TuiApplication.RunWithPalette(Initial, NotesUpdate, NotesView, NotesPalette())
    end;
    Error(Message):
    begin
      Std.Console.WriteLn('Could not open notes: ' + Message)
    end
  end
end.

# First program

## A first taste

```pascal
program Greet;

uses
  Std.Console;

function Greet(Name: string): string;
begin
  return 'Hello, ' + Name + '!';
end;

begin
  var Message: string := Greet('Pascal');
  WriteLn(Message);
end.
```

## Program structure

Every Functional Pascal program starts with a `program` declaration, optional `uses` clauses, then declarations and the main block:

```pascal
program MyApp;

uses
  Std.Console;

// constant declarations
const
  MaxItems: integer := 100;

// variable declarations
var
  Counter: integer := 0;

// function declarations
function Add(A: integer; B: integer): integer;
begin
  return A + B;
end;

// main block
begin
  WriteLn(Add(3, 4));
end.
```

The first segment `Std` in a unit name is reserved for the standard library. User-defined units use another root segment (for example `MyApp.Utils`); see [Units](../program-structure/units.md) and [Standard library](../std/README.md) for `uses` rules.

