unit Mandelbrot.Color;

uses Std.Math, Std.Tui;

public type
  PaletteKind = enum
    DeepOcean;
    Ember;
    Aurora;
  end;

public function PaletteName(Kind: PaletteKind): string;
begin
  case Kind of
    PaletteKind.DeepOcean:
    begin
      return 'Deep Ocean'
    end;
    PaletteKind.Ember:
    begin
      return 'Ember'
    end;
    PaletteKind.Aurora:
    begin
      return 'Aurora'
    end
  end
end;

function BandIndex(EscapeValue: real): integer;
begin
  return Clamp(Trunc(Frac(EscapeValue * 0.08) * 12.0), 0, 11)
end;

public function EscapeColor(Kind: PaletteKind; EscapeValue: real): TuiColor;
begin
  var Band: integer := BandIndex(EscapeValue);
  case Kind of
    PaletteKind.DeepOcean:
    begin
      case Band of
        0:
        begin
          return TuiColor.FromRgb(5, 16, 37)
        end;
        1:
        begin
          return TuiColor.FromRgb(11, 31, 70)
        end;
        2:
        begin
          return TuiColor.FromRgb(16, 51, 106)
        end;
