  WriteHudText(Title, Width);
  TextColorRGB(156, 204, 255);
  WriteHudText('  tasks | units | records | postfix | truecolor', Max(Width - Std.Str.Length(Title), 0));
  if ScreenHeight() >= 2 then
  begin
    GotoXY(1, 2);
    NormVideo();
    WriteHudText(Format('size=%dx%d  center=(%f, %f)  zoom=%f  iter=%d', Width, Height, S.CenterX, S.CenterY, S.Zoom, S.MaxIter), Width)
  end;

  if ScreenHeight() >= 3 then
  begin
    GotoXY(1, 3);
    NormVideo();
    WriteHudText('click center  wheel zoom  arrows  +/-  PgUp/Dn  R  Esc', Width)
  end;

  NormVideo();
  Window(1, 1, Width, Height)
end;

mutable var
  State: ExplorerState := ExplorerState.Default();
  RenderW: integer := 1;
  RenderH: integer := 1;
  NeedsRedraw: boolean := true;
  Quit: boolean := false;

procedure RequestRedraw();
begin
  NeedsRedraw := true
end;

procedure PaintFrame();
begin
  RenderW := RenderWidth();
  RenderH := RenderHeight();
  BeginFrame();
  FillRect(record
    x := 1;
    y := 1;
    width := ScreenWidth();
    height := ScreenHeight();
  end, record
    glyph := ' ';
    foreground := RgbColor(0, 0, 0);
    background := RgbColor(0, 0, 0);
  end);
  Render(State.XMin(RenderW, RenderH), State.XMax(RenderW, RenderH), State.YMin(), State.YMax(), RenderW, RenderH, State.MaxIter);
  DrawHud(State, RenderW, RenderH);
  Present()
end;

function HandleKey(Key: KeyEvent): boolean;
begin
  var StepX: real := State.SpanX(RenderW, RenderH) * 0.14;
  var StepY: real := State.SpanY * 0.14;
  if Key.kind = KeyKind.Escape then
  begin
    Quit := true;
    return true
  end
  else if Key.kind = KeyKind.Left then
  begin
    State.CenterX := State.CenterX - StepX;
    RequestRedraw();
    return true
  end
  else if Key.kind = KeyKind.Right then
  begin
    State.CenterX := State.CenterX + StepX;
    RequestRedraw();
    return true
  end
  else if Key.kind = KeyKind.Up then
  begin
    State.CenterY := State.CenterY + StepY;
    RequestRedraw();
    return true
  end
  else if Key.kind = KeyKind.Down then
  begin
    State.CenterY := State.CenterY - StepY;
    RequestRedraw();
    return true
  end
  else if Key.kind = KeyKind.PageUp then
  begin
    State.MaxIter := Min(State.MaxIter + 8, 256);
    RequestRedraw();
    return true
  end
  else if Key.kind = KeyKind.PageDown then
  begin
    State.MaxIter := Max(State.MaxIter - 8, 8);
    RequestRedraw();
    return true
  end
  else if Key.kind = KeyKind.Character then
  begin
    case Key.ch of
      '+', '=':
      begin
        State.SpanY := Max(State.SpanY * 0.82, 0.000001);
        RequestRedraw();
        return true
      end;
      '-':
      begin
        State.SpanY := Min(State.SpanY / 0.82, 6.0);
        RequestRedraw();
        return true
      end;
      'r', 'R':
      begin
        State := ExplorerState.Default();
        RequestRedraw();
        return true
      end
    end
  end;

  return false
end;

procedure HandleMouse(Event: Event);
begin
  var InView: boolean := Event.mouse_x >= 1;
  if Event.mouse_action = MouseAction.ScrollUp then
  begin
    State.SpanY := Max(State.SpanY * 0.88, 0.000001);
    RequestRedraw()
  end
  else if Event.mouse_action = MouseAction.ScrollDown then
  begin
    State.SpanY := Min(State.SpanY / 0.88, 6.0);
    RequestRedraw()
  end
  else if InView and (Event.mouse_action = MouseAction.Down) then
  begin
    if Event.mouse_button = MouseButton.Left then
    begin
      State.CenterX := ViewportCX(State, RenderW, RenderH, Event.mouse_x);
      State.CenterY := ViewportCY(State, RenderW, RenderH, Event.mouse_y);
      RequestRedraw()
    end
    else if Event.mouse_button = MouseButton.Middle then
    begin
      State := ExplorerState.Default();
      RequestRedraw()
    end
  end
end;

procedure HandleResize(Width: integer; Height: integer);
begin
  var NewW: integer := Max(Width, 1);
  var NewH: integer := Max(Height - 2, 1);
  if (NewW <> RenderW) or (NewH <> RenderH) then
  begin
    RenderW := NewW;
    RenderH := NewH;
    RequestRedraw()
  end
end;

procedure HandleEvent(E: Event);
begin
  if E.kind = EventKind.Key then
  begin
    HandleKey(E.key)
  end
  else if E.kind = EventKind.Mouse then
  begin
    HandleMouse(E)
  end
  else if E.kind = EventKind.Resize then
  begin
    HandleResize(E.width, E.height)
  end
end;

procedure ShutdownTerminal();
begin
  CursorOn();
  DisablePaste();
  DisableFocus();
  DisableMouse();
  DisableRawMode();
  LeaveAltScreen()
end;

begin
  EnableRawMode();
  EnterAltScreen();
  EnableMouse();
  EnableFocus();
  EnablePaste();
  CursorOff();
  RenderW := RenderWidth();
  RenderH := RenderHeight();
  NeedsRedraw := true;
  while not Quit do
  begin
    if NeedsRedraw then
    begin
      PaintFrame();
      NeedsRedraw := false
    end;

    case ReadEventTimeout(16) of
      Some(E):
      begin
        HandleEvent(E)
      end;
      None:
      begin
      end
    end
  end;

  ShutdownTerminal()
end.

