  RenderW: integer := 1;
  RenderH: integer := 1;
  NeedsRedraw: boolean := true;
  Quit: boolean := false;

procedure RequestRedraw();
begin
  NeedsRedraw := true
end;

procedure PaintFrame();
begin
  RenderW := RenderWidth();
  RenderH := RenderHeight();
  BeginFrame();
  FillRect(record
    x := 1;
    y := 1;
    width := ScreenWidth();
    height := ScreenHeight();
  end, record
    glyph := ' ';
    foreground := RgbColor(0, 0, 0);
    background := RgbColor(0, 0, 0);
  end);
  Render(State.XMin(RenderW, RenderH), State.XMax(RenderW, RenderH), State.YMin(), State.YMax(), RenderW, RenderH, State.MaxIter, State.Palette);
  DrawHud(State, RenderW, RenderH);
  Present()
end;

function HandleKey(Key: KeyEvent): boolean;
begin
  var StepX: real := State.SpanX(RenderW, RenderH) * 0.14;
  var StepY: real := State.SpanY * 0.14;
  if Key.kind = KeyKind.Escape then
  begin
    Quit := true;
    return true
  end
  else if Key.kind = KeyKind.Left then
  begin
    State.CenterX := State.CenterX - StepX;
    RequestRedraw();
    return true
  end
  else if Key.kind = KeyKind.Right then
  begin
    State.CenterX := State.CenterX + StepX;
    RequestRedraw();
    return true
  end
  else if Key.kind = KeyKind.Up then
  begin
    State.CenterY := State.CenterY + StepY;
    RequestRedraw();
    return true
  end
  else if Key.kind = KeyKind.Down then
  begin
    State.CenterY := State.CenterY - StepY;
    RequestRedraw();
    return true
  end
  else if Key.kind = KeyKind.PageUp then
  begin
    State.MaxIter := Min(State.MaxIter + 32, 2048);
    RequestRedraw();
    return true
  end
  else if Key.kind = KeyKind.PageDown then
  begin
    State.MaxIter := Max(State.MaxIter - 32, 32);
    RequestRedraw();
    return true
  end
  else if Key.kind = KeyKind.Character then
  begin
    case Key.ch of
      '+', '=':
      begin
        State.SpanY := Max(State.SpanY * 0.82, 0.000001);
        RequestRedraw();
        return true
      end;
      '-':
      begin
        State.SpanY := Min(State.SpanY / 0.82, 4.0);
        RequestRedraw();
        return true
      end;
      '1':
      begin
        State.Palette := PaletteKind.Aurora;
        RequestRedraw();
        return true
      end;
      '2':
      begin
        State.Palette := PaletteKind.Ember;
        RequestRedraw();
        return true
      end;
      '3':
      begin
        State.Palette := PaletteKind.Aurora;
        RequestRedraw();
        return true
      end;
      'r', 'R':
      begin
        State := ExplorerState.Default();
        RequestRedraw();
        return true
      end
    end
  end;

  return false
end;

procedure HandleMouse(Event: Event);
begin
  var InView: boolean := Event.mouse_x >= 1;
  if Event.mouse_action = MouseAction.ScrollUp then
  begin
    State.SpanY := Max(State.SpanY * 0.88, 0.000001);
    RequestRedraw()
  end
  else if Event.mouse_action = MouseAction.ScrollDown then
  begin
    State.SpanY := Min(State.SpanY / 0.88, 4.0);
    RequestRedraw()
  end
  else if InView and (Event.mouse_action = MouseAction.Down) then
  begin
    if Event.mouse_button = MouseButton.Left then
    begin
      State.CenterX := ViewportCX(State, RenderW, RenderH, Event.mouse_x);
      State.CenterY := ViewportCY(State, RenderW, RenderH, Event.mouse_y);
      RequestRedraw()
    end
    else if Event.mouse_button = MouseButton.Middle then
    begin
      State := ExplorerState.Default();
      RequestRedraw()
    end
  end
end;

procedure HandleResize(Width: integer; Height: integer);
begin
  var NewW: integer := Max(Width, 1);
  var NewH: integer := Max(Height - 2, 1);
  if (NewW <> RenderW) or (NewH <> RenderH) then
  begin
    RenderW := NewW;
    RenderH := NewH;
    RequestRedraw()
  end
end;

procedure HandleEvent(E: Event);
begin
  if E.kind = EventKind.Key then
  begin
    HandleKey(E.key)
  end
  else if E.kind = EventKind.Mouse then
  begin
    HandleMouse(E)
  end
  else if E.kind = EventKind.Resize then
  begin
    HandleResize(E.width, E.height)
  end
end;

procedure ShutdownTerminal();
begin
  CursorOn();
  DisablePaste();
  DisableFocus();
  DisableMouse();
  DisableRawMode();
  LeaveAltScreen()
end;

begin
  EnableRawMode();
  EnterAltScreen();
  EnableMouse();
  EnableFocus();
  EnablePaste();
  CursorOff();
  RenderW := RenderWidth();
  RenderH := RenderHeight();
  NeedsRedraw := true;
  while not Quit do
  begin
    if NeedsRedraw then
    begin
      PaintFrame();
      NeedsRedraw := false
    end;

    case ReadEventTimeout(16) of
      Some(E):
      begin
        HandleEvent(E)
      end;
      None:
      begin
      end
    end
  end;

  ShutdownTerminal()
end.

// Built only via tricorn.fpasprj — not a standalone program.

unit Tricorn.Render;

uses Std.Console, Std.Task, Std.Array, Std.Conv, Std.Math, Std.Str, Tricorn.Color;

type
  Complex = record
    public Re: real;
    public Im: real;

    public static function Zero(): Complex;
    begin
      return record
        Re := 0.0;
        Im := 0.0;
      end
    end;

    public static function Create(Re: real; Im: real): Complex;
    begin
      return record
        Re := Re;
        Im := Im;
      end
    end;

    public function Conj(Self: Complex): Complex;
    begin
      return record
        Re := Self.Re;
        Im := - Self.Im;
      end
    end;

    public function Sq(Self: Complex): Complex;
    begin
      return record
        Re := Self.Re * Self.Re - Self.Im * Self.Im;
        Im := (2.0 * Self.Re) * Self.Im;
      end
    end;

    public function Add(Self: Complex; Other: Complex): Complex;
    begin
      return record
        Re := Self.Re + Other.Re;
        Im := Self.Im + Other.Im;
      end
    end;

    public function MagSq(Self: Complex): real;
    begin
      return Self.Re * Self.Re + Self.Im * Self.Im
    end;
  end;
  PixelSample = record
    public IsInside: boolean;
    public EscapeValue: real;
  end;

function Iterate(C: Complex; MaxIter: integer): PixelSample;
begin
  var EscapeRadiusSq: real := 256.0;
  mutable var Z: Complex := Complex.Zero();
  mutable var N: integer := 0;
  while (N < MaxIter) and (Z.MagSq() <= EscapeRadiusSq) do
  begin
    Z := Z.Conj().Sq().Add(C);
    N := N + 1
  end;

  if N >= MaxIter then
  begin
    return record
      IsInside := true;
      EscapeValue := 0.0;
    end
  end;
  var MagnitudeSq: real := Max(Z.MagSq(), 4.0);
  var Smooth: real := (IntToReal(N) + 1.0) - (Log(Log(MagnitudeSq) * 0.5) / Log(2.0));
  return record
    IsInside := false;
    EscapeValue := Smooth;
  end
end;

function ComputeRow(
  Py: integer;
  Width: integer;
  Height: integer;
  XMin: real;
  XMax: real;
  YMin: real;
  YMax: real;
  MaxIter: integer
): array of PixelSample;
begin
  mutable var WidthRange: integer := Width - 1;
  mutable var HeightRange: integer := Height - 1;
  if WidthRange < 1 then
  begin
    WidthRange := 1
  end;

  if HeightRange < 1 then
  begin
    HeightRange := 1
  end;
  var Wr: real := IntToReal(WidthRange);
  var Hr: real := IntToReal(HeightRange);
  var cy: real := YMax - (Py / Hr) * (YMax - YMin);
  mutable var Row: array of PixelSample := [];
  for Px: integer := 0 to Width - 1 do
  begin
    var cx: real := XMin + (Px / Wr) * (XMax - XMin);
    Push(Row, Iterate(Complex.Create(cx, cy), MaxIter))
  end;

  return Row
end;

function EscapeGlyph(EscapeValue: real): string;
begin
  var Ramp: string := ' ░▒▓█';
  var Count: integer := Std.Str.Length(Ramp);
  var Phase: real := Frac(EscapeValue * 0.08);
  var Index: integer := Clamp(Trunc(Phase * IntToReal(Count)), 0, Count - 1);
  return CharAt(Ramp, Index)
end;

function RenderCell(Sample: PixelSample; Palette: PaletteKind): Cell;
begin
  if Sample.IsInside then
  begin
    var CellShade: Color := InsideColor();
    return record
      glyph := ' ';
      foreground := CellShade;
      background := CellShade;
    end
  end;

  return record
    glyph := EscapeGlyph(Sample.EscapeValue);
    foreground := EscapeColor(Palette, Sample.EscapeValue);
    background := RgbColor(0, 0, 0);
  end
end;

procedure DrawRow(Row: array of PixelSample; Width: integer; Y: integer; Palette: PaletteKind);
begin
  var CurrentWidth: integer := ScreenWidth();
  mutable var DrawWidth: integer := Width;
  if DrawWidth > CurrentWidth then
  begin
    DrawWidth := CurrentWidth
  end;

  if DrawWidth < 1 then
  begin
    return
  end;
  mutable var Cells: array of Cell := [];
  for Px: integer := 0 to DrawWidth - 1 do
  begin
    Push(Cells, RenderCell(Row[Px], Palette))
  end;

  WriteCells(1, Y, Cells)
end;

public procedure Render(
  XMin: real;
  XMax: real;
  YMin: real;
  YMax: real;
  Width: integer;
  Height: integer;
  MaxIter: integer;
  Palette: PaletteKind
);
begin
  mutable var Tasks: array of task := [];
  for Py: integer := 0 to Height - 1 do
  begin
    Push(Tasks, go ComputeRow(Py, Width, Height, XMin, XMax, YMin, YMax, MaxIter))
  end;

  for Py: integer := 0 to Height - 1 do
  begin
    var Row: array of PixelSample := Wait(Tasks[Py]);
    if (Py + 1) <= Max(ScreenHeight() - 2, 1) then
    begin
      DrawRow(Row, Width, Py + 1, Palette)
    end
  end
end;

