// Build first: cargo build --release -p fpas-cli
// Baseline: target/release/fpas run this-file.fpas -- 500
// Guard: target/release/fpas run this-file.fpas -- 500 MAX_MILLIS

program TuiHeadlessRenderBenchmark;

uses Std.Args, Std.Array, Std.Console, Std.Conv, Std.Time, Std.Tui;

const
  WarmupIterations: integer := 100;
  DeltaMillis: integer := 16;

function UpdateBenchmark(State: integer; Msg: TuiMsg; Cmd: TuiCmdOutput): integer;
begin
  Cmd.Set(TuiCmd.NoCommand);
  case Msg of
    TuiMsg.Tick(Delta):
    begin
      return State + 1
    end;
    TuiMsg.Key(Key):
    begin
      return State
    end;
    TuiMsg.Pointer(Pointer):
    begin
      return State
    end;
    TuiMsg.Resize(Size):
    begin
      return State
    end;
    TuiMsg.FocusChanged(Previous, Current):
    begin
      return State
    end;
    TuiMsg.Action(Source, Action):
    begin
      return State
    end;
    TuiMsg.TextChanged(Source, Action, Text, Caret):
    begin
      return State
    end;
    TuiMsg.TextAreaChanged(Source, Action, Text, Caret, TextAreaOffset):
    begin
      return State
    end;
    TuiMsg.CheckChanged(Source, Action, Checked):
    begin
      return State
    end;
    TuiMsg.SelectionChanged(Source, Action, Selected):
    begin
      return State
    end;
    TuiMsg.ScrollChanged(Source, Action, Offset):
    begin
      return State
    end;
    TuiMsg.MenuChanged(MenuSource, MenuAction, MenuState):
    begin
      return State
    end;
    TuiMsg.QuitRequested:
    begin
      return State
    end
  end
end;

function ViewBenchmark(State: integer): TuiElement;
begin
  mutable var Children: array of TuiElement := [
                                                 TuiElementBuilders.MakeLabel('frame ' + IntToStr(State))
                                               ];
  for Index: integer := 2 to 32 do
  begin
    Std.Array.Push(Children, TuiElementBuilders.MakeLabel('row'))
  end;
  var SharedAction: TuiAction := TuiAction.Create(100);
  for Index: integer := 1 to 8 do
  begin
    Std.Array.Push(Children, TuiElementBuilders.MakeButton(TuiControlId.Create(Index), 'action', SharedAction))
  end;

  return TuiElementBuilders.MakeDesktop(Some(TuiControlId.Create(1)), [
                                                                        TuiElementBuilders.MakePanel('Headless benchmark', [TuiElementBuilders.MakeColumn(Children)])
                                                                      ])
end;

begin
  if (ParamCount() < 1) or (ParamCount() > 2) then
  begin
    panic('usage: headless_render_benchmark.fpas -- ITERATIONS [MAX_MILLIS]')
  end;
  var Iterations: integer := StrToInt(ParamStr(0));
  if Iterations < 1 then
  begin
    panic('ITERATIONS must be positive')
  end;
  mutable var MaxMillis: integer := 0;
  if ParamCount() = 2 then
  begin
    MaxMillis := StrToInt(ParamStr(1));
    if MaxMillis < 1 then
    begin
      panic('MAX_MILLIS must be positive')
    end
  end;
  mutable var App: TuiApplication := TuiApplication.OpenForTest(TuiSize.Create(120, 40));
  mutable var Model: integer := App.RunIterations(0, UpdateBenchmark, ViewBenchmark, WarmupIterations, DeltaMillis);
  var Started: integer := MonotonicMillis();
  Model := App.RunIterations(Model, UpdateBenchmark, ViewBenchmark, Iterations, DeltaMillis);
  var Elapsed: integer := ElapsedMillis(Started);
  App.Close();
  mutable var FramesPerSecond: integer := Iterations * 1000;
  if Elapsed > 0 then
  begin
    FramesPerSecond := (Iterations * 1000) div Elapsed
  end;

  WriteLn((('iterations: ' + IntToStr(Iterations)) + ', warm-up: ') + IntToStr(WarmupIterations));
  WriteLn(('elapsed: ' + IntToStr(Elapsed)) + ' ms');
  WriteLn(('throughput: ' + IntToStr(FramesPerSecond)) + ' frames/s');
  WriteLn('final state: ' + IntToStr(Model));
  if (MaxMillis > 0) and (Elapsed > MaxMillis) then
  begin
    panic(((('TUI benchmark regression: ' + IntToStr(Elapsed)) + ' ms exceeds limit ') + IntToStr(MaxMillis)) +
          ' ms')
  end
end.

program TuiInteractiveDemo;

uses Std.Tui;

type
  DemoModel = record
    Text: string;
    Caret: integer;
    Confirming: boolean;
  end;

function UpdateDemo(State: DemoModel; Msg: TuiMsg; Cmd: TuiCmdOutput): DemoModel;
begin
  Cmd.Set(TuiCmd.NoCommand);
  case Msg of
    TuiMsg.TextChanged(Source, Action, Text, Caret):
    begin
      return record
        Text := Text;
        Caret := Caret;
        Confirming := State.Confirming;
      end
    end;
    TuiMsg.Action(Source, Action):
    begin
      if Action.Value = 2 then
      begin
        return record
          Text := State.Text;
          Caret := State.Caret;
          Confirming := true;
        end
      end;

      if Action.Value = 3 then
      begin
        Cmd.Set(TuiCmd.Quit)
      end;

      return State
    end;
    TuiMsg.QuitRequested:
    begin
      Cmd.Set(TuiCmd.Quit);
      return State
    end;
    TuiMsg.Key(Key):
    begin
      return State
    end;
    TuiMsg.Pointer(Pointer):
    begin
      return State
    end;
    TuiMsg.Tick(Delta):
    begin
      return State
    end;
    TuiMsg.Resize(Size):
    begin
      return State
    end;
    TuiMsg.FocusChanged(Previous, Current):
    begin
      return State
    end;
    TuiMsg.TextAreaChanged(Source, Action, Text, Caret, TextAreaOffset):
    begin
      return State
    end;
    TuiMsg.CheckChanged(Source, Action, Checked):
    begin
      return State
    end;
    TuiMsg.SelectionChanged(Source, Action, Selected):
    begin
      return State
    end;
    TuiMsg.ScrollChanged(Source, Action, Offset):
    begin
      return State
    end;
    TuiMsg.MenuChanged(MenuSource, MenuAction, MenuState):
