program TuiButtonPointerTest;

uses Std.Array, Std.Str, Std.Test, Std.Tui;

type
  ButtonPointerModel = record
    Actions: integer;
    PointerEvents: integer;
  end;

function ViewButton(State: ButtonPointerModel): TuiElement;
begin
  return TuiElementBuilders.MakeDesktop(Some(TuiControlId.Create(1)), [
                                                                        TuiElementBuilders.MakeButtonWithMnemonic(TuiControlId.Create(1), 'Go', 'G', TuiAction.Create(10))
                                                                      ])
end;

function UpdateButton(State: ButtonPointerModel; Msg: TuiMsg; Cmd: TuiCmdOutput): ButtonPointerModel;
begin
  Cmd.Set(TuiCmd.NoCommand);
  case Msg of
    TuiMsg.Action(Source, Action):
    begin
      return record
        Actions := State.Actions + 1;
        PointerEvents := State.PointerEvents;
      end
    end;
    TuiMsg.Pointer(Pointer):
    begin
      return record
        Actions := State.Actions;
        PointerEvents := State.PointerEvents + 1;
      end
    end
    else
    begin
      return State
    end
  end
end;

function Pointer(Action: TuiPointerAction; Position: TuiPoint): TuiPointerEvent;
begin
  return TuiPointerEvent.Create(Action, TuiPointerButton.Left, Position)
end;

begin
  var App: TuiApplication := TuiApplication.OpenForTest(TuiSize.Create(16, 4));
  mutable var Model: ButtonPointerModel := record
    Actions := 0;
    PointerEvents := 0;
  end;

  Model := App.RunIterations(Model, UpdateButton, ViewButton, 0, 0);
  var GoX: integer := Std.Str.IndexOf(App.SurfaceSnapshot().LineAt(0), 'G');
  var Inside: TuiPoint := TuiPoint.Create(GoX, 0);
  App.InjectPointerForTest(Pointer(TuiPointerAction.Down, Inside));
  Model := App.RunIterations(Model, UpdateButton, ViewButton, 1, 0);
  AssertEquals(0, Model.Actions);
  AssertEquals(1, Model.PointerEvents);
  App.InjectPointerForTest(Pointer(TuiPointerAction.Drag, TuiPoint.Create(15, 3)));
  Model := App.RunIterations(Model, UpdateButton, ViewButton, 1, 0);
  App.InjectPointerForTest(Pointer(TuiPointerAction.Up, TuiPoint.Create(15, 3)));
  Model := App.RunIterations(Model, UpdateButton, ViewButton, 1, 0);
  AssertEquals(0, Model.Actions);
  App.InjectPointerForTest(Pointer(TuiPointerAction.Down, Inside));
  Model := App.RunIterations(Model, UpdateButton, ViewButton, 1, 0);
  App.InjectPointerForTest(Pointer(TuiPointerAction.Drag, TuiPoint.Create(15, 3)));
  Model := App.RunIterations(Model, UpdateButton, ViewButton, 1, 0);
  App.InjectPointerForTest(Pointer(TuiPointerAction.Drag, Inside));
  Model := App.RunIterations(Model, UpdateButton, ViewButton, 1, 0);
  App.InjectPointerForTest(Pointer(TuiPointerAction.Up, Inside));
  Model := App.RunIterations(Model, UpdateButton, ViewButton, 1, 0);
  AssertEquals(1, Model.Actions);
  App.Close()
end.

program TuiCanvasClipTest;

uses Std.Option, Std.Str, Std.Test, Std.Tui;

begin
  var Surface: TuiWorkingSurface := TuiWorkingSurface.Create(TuiSize.Create(6, 4));
  var Root: TuiCanvas := TuiCanvas.Create(Surface, TuiRect.Create(0, 0, 6, 4));
  var Child: TuiCanvas := Root.Child(TuiRect.Create(1, 1, 3, 2));
  Child.PutGlyph(0, 0, 'A');
  Child.PutGlyph(2, 1, 'B');
  Child.PutGlyph(-1, 0, 'Z');
  Child.PutGlyph(3, 0, 'Z');
  Child.PutGlyph(0, -1, 'Z');
  Child.PutGlyph(0, 2, 'Z');
  AssertEquals('A', Std.Option.Unwrap(Surface.TryCellAt(TuiPoint.Create(1, 1))).Glyph);
  AssertEquals('B', Std.Option.Unwrap(Surface.TryCellAt(TuiPoint.Create(3, 2))).Glyph);
  AssertEquals(' ', Std.Option.Unwrap(Surface.TryCellAt(TuiPoint.Create(0, 1))).Glyph);
  AssertEquals(' ', Std.Option.Unwrap(Surface.TryCellAt(TuiPoint.Create(4, 1))).Glyph);
  AssertEquals(' ', Std.Option.Unwrap(Surface.TryCellAt(TuiPoint.Create(1, 0))).Glyph);
  AssertEquals(' ', Std.Option.Unwrap(Surface.TryCellAt(TuiPoint.Create(1, 3))).Glyph);
  var Nested: TuiCanvas := Child.Child(TuiRect.Create(1, 0, 2, 1));
  Nested.FillRect(TuiRect.Create(-1, -1, 4, 3), TuiCell.Create('#', TuiStyleRole.Accent));
  AssertEquals('A', Std.Option.Unwrap(Surface.TryCellAt(TuiPoint.Create(1, 1))).Glyph);
  AssertEquals('#', Std.Option.Unwrap(Surface.TryCellAt(TuiPoint.Create(2, 1))).Glyph);
  AssertEquals('#', Std.Option.Unwrap(Surface.TryCellAt(TuiPoint.Create(3, 1))).Glyph);
  AssertEquals(' ', Std.Option.Unwrap(Surface.TryCellAt(TuiPoint.Create(4, 1))).Glyph);
  AssertEquals('B', Std.Option.Unwrap(Surface.TryCellAt(TuiPoint.Create(3, 2))).Glyph);
  Root.WriteText(TuiPoint.Create(0, 3), ('Hi' + Std.Str.Chr(10)) + 'No', TuiStyleRole.Title);
  AssertEquals('H', Std.Option.Unwrap(Surface.TryCellAt(TuiPoint.Create(0, 3))).Glyph);
  AssertEquals('i', Std.Option.Unwrap(Surface.TryCellAt(TuiPoint.Create(1, 3))).Glyph);
  AssertEquals(' ', Std.Option.Unwrap(Surface.TryCellAt(TuiPoint.Create(2, 3))).Glyph)
end.

program TuiCheckBoxKeyboardTest;

uses Std.Array, Std.Test, Std.Tui;

type
  CheckModel = record
    Focus: integer;
    Checked: boolean;
    Changes: array of boolean;
  end;

function MakeKey(Kind: TuiKeyKind; Character: string): TuiKeyEvent;
begin
  return record
    kind := Kind;
    ch := Character;
    shift := false;
    ctrl := false;
    alt := false;
    meta := false;
  end
end;

function ViewCheck(State: CheckModel): TuiElement;
begin
  return TuiElementBuilders.MakeDesktop(Some(TuiControlId.Create(State.Focus)), [
                                                                                  TuiElementBuilders.MakePanel('Host', [
                                                                                                                         TuiElementBuilders.MakeCheckBox(TuiControlId.Create(1), 'Flag', State.Checked, TuiAction.Create(9))
                                                                                                                       ])
                                                                                ])
end;

function UpdateCheck(State: CheckModel; Msg: TuiMsg; Cmd: TuiCmdOutput): CheckModel;
begin
  Cmd.Set(TuiCmd.NoCommand);
  case Msg of
    TuiMsg.FocusChanged(Previous, Current):
    begin
      case Current of
        Some(Id):
        begin
          return record
            Focus := Id.Value;
            Checked := State.Checked;
            Changes := State.Changes;
          end
        end;
        None:
        begin
          return State
        end
      end
    end;
    TuiMsg.CheckChanged(Source, Action, Checked):
    begin
      AssertEquals(1, Source.Value);
      AssertEquals(9, Action.Value);
      return record
        Focus := State.Focus;
        Checked := Checked;
        Changes := Std.Array.Concat(State.Changes, [Checked]);
      end
    end
    else
    begin
      return State
    end
  end
end;

begin
  mutable var App: TuiApplication := TuiApplication.OpenForTest(TuiSize.Create(24, 6));
  mutable var Model: CheckModel := record
    Focus := 1;
    Checked := false;
    Changes := [];
  end;

  Model := App.RunIterations(Model, UpdateCheck, ViewCheck, 0, 0);
  App.InjectKeyForTest(MakeKey(TuiKeyKind.Space, ''));
  Model := App.RunIterations(Model, UpdateCheck, ViewCheck, 1, 0);
  AssertTrue(Model.Checked);
  AssertEquals(1, Std.Array.Length(Model.Changes));
  AssertTrue(Model.Changes[0]);
  App.InjectKeyForTest(MakeKey(TuiKeyKind.Enter, ''));
  Model := App.RunIterations(Model, UpdateCheck, ViewCheck, 1, 0);
  AssertFalse(Model.Checked);
  AssertEquals(2, Std.Array.Length(Model.Changes));
  AssertFalse(Model.Changes[1]);
  App.Close()
end.

program TuiCheckBoxPointerTest;

uses Std.Array, Std.Str, Std.Test, Std.Tui;

type
  CheckModel = record
    Focus: integer;
    Checked: boolean;
