program TuiGeometryValuesTest;

uses Std.Test, Std.Tui;

begin
  var Point: TuiPoint := TuiPoint.Create(5, 7);
  AssertEquals(5, Point.X);
  AssertEquals(7, Point.Y);
  var Size: TuiSize := TuiSize.Create(12, 4);
  AssertFalse(Size.IsEmpty());
  var EmptySize: TuiSize := TuiSize.Create(0, 4);
  AssertTrue(EmptySize.IsEmpty());
  var ZeroHeight: TuiSize := TuiSize.Create(3, 0);
  AssertTrue(ZeroHeight.IsEmpty());
  var Bounds: TuiRect := TuiRect.Create(2, 3, 8, 5);
  AssertEquals(10, Bounds.Right());
  AssertEquals(8, Bounds.Bottom());
  AssertFalse(Bounds.IsEmpty());
  AssertTrue(Bounds.Contains(TuiPoint.Create(2, 3)));
  AssertTrue(Bounds.Contains(TuiPoint.Create(9, 7)));
  AssertFalse(Bounds.Contains(TuiPoint.Create(10, 7)));
  AssertFalse(Bounds.Contains(TuiPoint.Create(9, 8)));
  AssertFalse(Bounds.Contains(TuiPoint.Create(1, 3)));
  AssertFalse(Bounds.Contains(TuiPoint.Create(2, 2)));
  var Edges: TuiRect := TuiRect.FromEdges(2, 3, 10, 8);
  AssertEquals(8, Edges.Width);
  AssertEquals(5, Edges.Height);
  var PointSize: TuiRect := TuiRect.FromPointSize(TuiPoint.Create(2, 3), TuiSize.Create(8, 5));
  AssertEquals(10, PointSize.Right());
  AssertEquals(8, PointSize.Bottom());
  var Corners: TuiRect := TuiRect.FromCorners(TuiPoint.Create(2, 3), TuiPoint.Create(10, 8));
  AssertEquals(5, Corners.Height);
  var Overlap: TuiRect := Bounds.Intersect(TuiRect.Create(6, 1, 8, 6));
  AssertEquals(6, Overlap.X);
  AssertEquals(3, Overlap.Y);
  AssertEquals(4, Overlap.Width);
  AssertEquals(4, Overlap.Height);
  AssertTrue(Bounds.Intersects(Overlap));
  var Empty: TuiRect := Bounds.Intersect(TuiRect.Create(10, 3, 2, 2));
  AssertTrue(Empty.IsEmpty());
  AssertFalse(Bounds.Intersects(TuiRect.Create(10, 3, 2, 2)));
  var Inset: TuiRect := Bounds.Inset();
  AssertEquals(3, Inset.X);
  AssertEquals(4, Inset.Y);
  AssertEquals(6, Inset.Width);
  AssertEquals(3, Inset.Height);
  var Thin: TuiRect := TuiRect.Create(0, 0, 1, 1).Inset();
  AssertTrue(Thin.IsEmpty());
  var EmptyInset: TuiRect := TuiRect.Create(4, 5, 0, 2).Inset();
  AssertTrue(EmptyInset.IsEmpty())
end.

program TuiInputKeyboardTest;

uses Std.Test, Std.Tui;

type
  InputKeyboardModel = record
    Text: string;
    Caret: integer;
    UseHistory: boolean;
    KeyHits: integer;
  end;

function MakeKey(Kind: TuiKeyKind; Ctrl: boolean): TuiKeyEvent;
begin
  return record
    kind := Kind;
    ch := '';
    shift := false;
    ctrl := Ctrl;
    alt := false;
    meta := false;
  end
end;

function ViewInput(State: InputKeyboardModel): TuiElement;
begin
  mutable var Input: TuiElement := TuiElementBuilders.MakeInputWithHint(TuiControlId.Create(1), State.Text, State.Caret, 'Command', TuiAction.Create(1));
  if State.UseHistory then
  begin
    Input := TuiElementBuilders.MakeHistoryInput(TuiControlId.Create(1), State.Text, State.Caret, 'Command', [
                                                                                                               'first',
                                                                                                               'second'
                                                                                                             ], 'draft', TuiAction.Create(1))
  end;

  return TuiElementBuilders.MakeDesktop(Some(TuiControlId.Create(1)), [Input])
end;

function UpdateInput(State: InputKeyboardModel; Msg: TuiMsg; Cmd: TuiCmdOutput): InputKeyboardModel;
begin
  Cmd.Set(TuiCmd.NoCommand);
  case Msg of
    TuiMsg.TextChanged(Source, Action, Text, Caret):
    begin
      return record
        Text := Text;
        Caret := Caret;
        UseHistory := State.UseHistory;
        KeyHits := State.KeyHits;
      end
    end;
    TuiMsg.Key(Key):
    begin
      return record
        Text := State.Text;
        Caret := State.Caret;
        UseHistory := State.UseHistory;
        KeyHits := State.KeyHits + 1;
      end
    end
    else
    begin
      return State
    end
  end
end;

function Press(App: TuiApplication; State: InputKeyboardModel; Kind: TuiKeyKind; Ctrl: boolean): InputKeyboardModel;
begin
  App.InjectKeyForTest(MakeKey(Kind, Ctrl));
  return App.RunIterations(State, UpdateInput, ViewInput, 1, 0)
end;

begin
  mutable var App: TuiApplication := TuiApplication.OpenForTest(TuiSize.Create(20, 2));
  mutable var Model: InputKeyboardModel := record
    Text := 'alpha beta';
    Caret := 10;
    UseHistory := false;
    KeyHits := 0;
  end;

  Model := App.RunIterations(Model, UpdateInput, ViewInput, 0, 0);
  Model := Press(App, Model, TuiKeyKind.Left, true);
  AssertEquals(6, Model.Caret);
  Model := Press(App, Model, TuiKeyKind.Backspace, true);
  AssertEquals('beta', Model.Text);
  AssertEquals(0, Model.Caret);
  Model := record
    Text := 'alpha beta';
    Caret := 0;
    UseHistory := false;
    KeyHits := 0;
  end;

  Model := App.RunIterations(Model, UpdateInput, ViewInput, 0, 0);
  Model := Press(App, Model, TuiKeyKind.Delete, true);
  AssertEquals('beta', Model.Text);
  AssertEquals(0, Model.Caret);
  Model := Press(App, Model, TuiKeyKind.Up, false);
  AssertEquals(1, Model.KeyHits);
  Model := record
    Text := 'draft';
    Caret := 5;
    UseHistory := true;
    KeyHits := 0;
  end;

  Model := App.RunIterations(Model, UpdateInput, ViewInput, 0, 0);
  Model := Press(App, Model, TuiKeyKind.Up, false);
  AssertEquals('second', Model.Text);
  Model := Press(App, Model, TuiKeyKind.Up, false);
  AssertEquals('first', Model.Text);
  Model := Press(App, Model, TuiKeyKind.Up, false);
  AssertEquals('first', Model.Text);
  AssertEquals(0, Model.KeyHits);
  Model := Press(App, Model, TuiKeyKind.Down, false);
  AssertEquals('second', Model.Text);
  Model := Press(App, Model, TuiKeyKind.Down, false);
  AssertEquals('draft', Model.Text);
  AssertEquals(5, Model.Caret);
  Model := Press(App, Model, TuiKeyKind.Down, false);
  AssertEquals('draft', Model.Text);
  AssertEquals(0, Model.KeyHits);
  App.Close()
end.

