program TuiTextAreaKeyboardTest;

uses Std.Str, Std.Test, Std.Tui;

type
  TextAreaModel = record
    Text: string;
    Caret: integer;
    Offset: TuiPoint;
  end;

function MakeKey(Kind: TuiKeyKind; Character: string): TuiKeyEvent;
begin
  return record
    kind := Kind;
    ch := Character;
    shift := false;
    ctrl := false;
    alt := false;
    meta := false;
  end
end;

function ViewTextArea(State: TextAreaModel): TuiElement;
begin
  return TuiElementBuilders.MakeDesktop(Some(TuiControlId.Create(1)), [
                                                                        TuiElementBuilders.MakeTextArea(TuiControlId.Create(1), State.Text, State.Caret, State.Offset, TuiAction.Create(9))
                                                                      ])
end;

function ViewWindowedTextArea(State: TextAreaModel): TuiElement;
begin
  var Editor: TuiElement := TuiElementBuilders.MakeTextArea(TuiControlId.Create(1), State.Text, State.Caret, State.Offset, TuiAction.Create(9));
  return TuiElementBuilders.MakeDesktop(Some(TuiControlId.Create(1)), [
                                                                        TuiElementBuilders.MakePanel('Editor', [Editor])
                                                                      ])
end;

function UpdateTextArea(State: TextAreaModel; Msg: TuiMsg; Cmd: TuiCmdOutput): TextAreaModel;
begin
  Cmd.Set(TuiCmd.NoCommand);
  case Msg of
    TuiMsg.TextAreaChanged(Source, Action, Text, Caret, Offset):
    begin
      AssertEquals(1, Source.Value);
      AssertEquals(9, Action.Value);
      return record
        Text := Text;
        Caret := Caret;
        Offset := Offset;
      end
    end
    else
    begin
      return State
    end
  end
end;

function Press(App: TuiApplication; State: TextAreaModel; Kind: TuiKeyKind; Character: string): TextAreaModel;
begin
  App.InjectKeyForTest(MakeKey(Kind, Character));
  return App.RunIterations(State, UpdateTextArea, ViewTextArea, 1, 0)
end;

function PressWindowed(
  App: TuiApplication;
  State: TextAreaModel;
  Kind: TuiKeyKind;
  Character: string
): TextAreaModel;
begin
  App.InjectKeyForTest(MakeKey(Kind, Character));
  return App.RunIterations(State, UpdateTextArea, ViewWindowedTextArea, 1, 0)
end;

begin
  mutable var App: TuiApplication := TuiApplication.OpenForTest(TuiSize.Create(6, 2));
  mutable var Model: TextAreaModel := record
    Text := 'ab';
    Caret := 2;
    Offset := TuiPoint.Create(0, 0);
  end;

  Model := App.RunIterations(Model, UpdateTextArea, ViewTextArea, 0, 0);
  Model := Press(App, Model, TuiKeyKind.Enter, '');
  AssertEquals(('ab' + Std.Str.Chr(10)), Model.Text);
  AssertEquals(3, Model.Caret);
  Model := Press(App, Model, TuiKeyKind.Character, 'x');
  AssertEquals((('ab' + Std.Str.Chr(10)) + 'x'), Model.Text);
  Model := Press(App, Model, TuiKeyKind.Backspace, '');
  Model := Press(App, Model, TuiKeyKind.Backspace, '');
  AssertEquals('ab', Model.Text);
  AssertEquals(2, Model.Caret);
  Model := Press(App, Model, TuiKeyKind.Tab, '');
  AssertEquals('ab  ', Model.Text);
  AssertEquals(4, Model.Caret);
  Model := Press(App, Model, TuiKeyKind.Home, '');
  AssertEquals(0, Model.Caret);
  Model := Press(App, Model, TuiKeyKind.EndKey, '');
  AssertEquals(4, Model.Caret);
  Model := Press(App, Model, TuiKeyKind.Left, '');
  Model := Press(App, Model, TuiKeyKind.Delete, '');
  AssertEquals('ab ', Model.Text);
  AssertEquals(3, Model.Caret);
  Model := record
    Text := ((('abcd' + Std.Str.Chr(10)) + 'x') + Std.Str.Chr(10)) + (('wxyz' + Std.Str.Chr(10)) + 'last');
    Caret := 3;
    Offset := TuiPoint.Create(0, 0);
  end;

  Model := App.RunIterations(Model, UpdateTextArea, ViewTextArea, 0, 0);
  Model := Press(App, Model, TuiKeyKind.Down, '');
  AssertEquals(6, Model.Caret);
  Model := Press(App, Model, TuiKeyKind.Down, '');
  AssertEquals(8, Model.Caret);
  Model := Press(App, Model, TuiKeyKind.Up, '');
  AssertEquals(6, Model.Caret);
  Model := Press(App, Model, TuiKeyKind.PageDown, '');
  AssertEquals(13, Model.Caret);
  AssertEquals(2, Model.Offset.Y);
  Model := Press(App, Model, TuiKeyKind.PageUp, '');
  AssertEquals(6, Model.Caret);
  AssertEquals(1, Model.Offset.Y);
  App.Close();
  App := TuiApplication.OpenForTest(TuiSize.Create(4, 2));
  Model := record
    Text := 'abcdef';
    Caret := 0;
    Offset := TuiPoint.Create(0, 0);
  end;

  Model := App.RunIterations(Model, UpdateTextArea, ViewTextArea, 0, 0);
  Model := Press(App, Model, TuiKeyKind.EndKey, '');
  AssertEquals(6, Model.Caret);
  AssertEquals(3, Model.Offset.X);
  Model := record
    Text := ('one' + Std.Str.Chr(10)) + 'abcd';
    Caret := 6;
    Offset := TuiPoint.Create(1, 1);
  end;

  Model := App.RunIterations(Model, UpdateTextArea, ViewTextArea, 0, 0);
  Model := Press(App, Model, TuiKeyKind.Right, '');
  AssertEquals(7, Model.Caret);
  AssertEquals(1, Model.Offset.X);
  AssertEquals(1, Model.Offset.Y);
  App.Inject(TuiMsgTextAreaChanged(TuiControlId.Create(1), TuiAction.Create(9), 'done', 4, TuiPoint.Create(0, 0)));
  Model := App.RunIterations(Model, UpdateTextArea, ViewTextArea, 1, 0);
  AssertEquals('done', Model.Text);
  AssertEquals(4, Model.Caret);
  AssertEquals(0, Model.Offset.X);
  AssertEquals(0, Model.Offset.Y);
  App.Close();
  App := TuiApplication.OpenForTest(TuiSize.Create(10, 5));
  Model := record
    Text := 'first';
    Caret := 5;
    Offset := TuiPoint.Create(0, 0);
  end;

  Model := App.RunIterations(Model, UpdateTextArea, ViewWindowedTextArea, 0, 0);
  Model := PressWindowed(App, Model, TuiKeyKind.Enter, '');
  AssertEquals(0, Model.Offset.Y);
  AssertTrue(Std.Str.Contains(App.SurfaceSnapshot().LineAt(1), 'first'));
  App.Close()
end.

program TuiTextAreaLayoutTest;

uses Std.Str, Std.Test, Std.Tui;

function Paint(Tree: TuiElement; Size: TuiSize): TuiSurfaceSnapshot;
begin
  var App: TuiApplication := TuiApplication.OpenForTest(Size);
  App.RunIterations(Tree, function(State: TuiElement; Msg: TuiMsg; Cmd: TuiCmdOutput): TuiElement begin
    return State
  end, function(State: TuiElement): TuiElement begin
    return State
  end, 0, 0);
  var Snapshot: TuiSurfaceSnapshot := App.SurfaceSnapshot();
  App.Close();
  return Snapshot
end;

begin
  var TextArea: TuiElement := TuiElementBuilders.MakeTextArea(TuiControlId.Create(1), ('abc' + Std.Str.Chr(10)) +
                                                                                      '12345', 0, TuiPoint.Create(0, 0), TuiAction.Create(9));
  var Measured: TuiMeasureResult := TuiMeasure(TextArea, TuiMeasureSpec.Unbounded());
  AssertEquals(1, Measured.Minimum.Width);
  AssertEquals(1, Measured.Minimum.Height);
  AssertEquals(5, Measured.Preferred.Width);
  AssertEquals(2, Measured.Preferred.Height);
  AssertTrue(Measured.Maximum.Width > Measured.Preferred.Width);
  AssertTrue(Measured.Maximum.Height > Measured.Preferred.Height);
  var Constrained: TuiMeasureResult := TuiMeasure(TextArea, TuiMeasureSpec.AtMost(TuiSize.Create(3, 1)));
  AssertEquals(3, Constrained.Preferred.Width);
  AssertEquals(1, Constrained.Preferred.Height);
  var Filled: TuiSurfaceSnapshot := Paint(TuiElementBuilders.MakeDesktop(None, [
                                                                                 TuiElementBuilders.MakeColumn([
                                                                                                                 TuiElementBuilders.MakeTextArea(TuiControlId.Create(1), 'x', 0, TuiPoint.Create(0, 0), TuiAction.Create(9)),
                                                                                                                 TuiElementBuilders.MakeLabel('tail')
                                                                                                               ])
                                                                               ]), TuiSize.Create(8, 4));
  AssertEquals('t', Filled.CellAt(0, 3).Glyph)
end.

program TuiTextAreaPointerTest;

uses Std.Str, Std.Test, Std.Tui;

type
  PointerModel = record
    Focus: integer;
    Text: string;
    Caret: integer;
    Offset: TuiPoint;
  end;

function ViewTextArea(State: PointerModel): TuiElement;
begin
  mutable var Focused: option of TuiControlId := None;
  if State.Focus > 0 then
  begin
    Focused := Some(TuiControlId.Create(State.Focus))
  end;

  return TuiElementBuilders.MakeDesktop(Focused, [
                                                   TuiElementBuilders.MakeTextArea(TuiControlId.Create(1), State.Text, State.Caret, State.Offset, TuiAction.Create(9))
                                                 ])
end;

function UpdateTextArea(State: PointerModel; Msg: TuiMsg; Cmd: TuiCmdOutput): PointerModel;
begin
  Cmd.Set(TuiCmd.NoCommand);
  case Msg of
    TuiMsg.FocusChanged(Previous, Current):
    begin
      case Current of
        Some(Id):
        begin
          return record
            Focus := Id.Value;
            Text := State.Text;
            Caret := State.Caret;
            Offset := State.Offset;
          end
        end;
        None:
        begin
          return State
        end
      end
    end;
    TuiMsg.TextAreaChanged(Source, Action, Text, Caret, Offset):
    begin
      AssertEquals(1, Source.Value);
      AssertEquals(9, Action.Value);
      return record
        Focus := State.Focus;
        Text := Text;
        Caret := Caret;
        Offset := Offset;
      end
    end
    else
    begin
      return State
    end
  end
end;

function Click(
  App: TuiApplication;
  State: PointerModel;
  X: integer;
  Y: integer;
  Iterations: integer
): PointerModel;
begin
  App.InjectPointerForTest(TuiPointerEvent.Create(TuiPointerAction.Down, TuiPointerButton.Left, TuiPoint.Create(X, Y)));
  return App.RunIterations(State, UpdateTextArea, ViewTextArea, Iterations, 0)
end;

begin
  mutable var App: TuiApplication := TuiApplication.OpenForTest(TuiSize.Create(6, 3));
  mutable var Model: PointerModel := record
    Focus := 0;
    Text := (('zero' + Std.Str.Chr(10)) + 'one') + (Std.Str.Chr(10) + 'three');
    Caret := 0;
    Offset := TuiPoint.Create(0, 0);
  end;

  Model := App.RunIterations(Model, UpdateTextArea, ViewTextArea, 0, 0);
  Model := Click(App, Model, 2, 1, 2);
  AssertEquals(1, Model.Focus);
  AssertEquals(7, Model.Caret);
  Model := Click(App, Model, 5, 1, 1);
  AssertEquals(8, Model.Caret);
  Model := record
    Focus := 1;
    Text := Model.Text;
    Caret := Model.Caret;
    Offset := TuiPoint.Create(2, 1);
  end;

  Model := App.RunIterations(Model, UpdateTextArea, ViewTextArea, 0, 0);
  Model := Click(App, Model, 1, 1, 1);
  AssertEquals(12, Model.Caret);
  AssertEquals(2, Model.Offset.X);
  AssertEquals(1, Model.Offset.Y);
  App.Close()
end.

